    # modified somewhat to allow for various levels of granularity in the
    # representation of time.
    len_str = len(timestr)
    pos = 0
    comps = [None, None, None, None]  # hour, minute, second, microsecond

    for i in range(0, 3):
        if pos >= len_str:
            break

        if timestr[pos:pos+2].isdigit():
            comps[i] = int(timestr[pos:pos+2])
            pos += 2
        else:
            raise ValueError('Unexpected character: {}'.format(timestr[pos]))

        if i < 2:
            if pos < len_str and timestr[pos:pos+1] in ',:':
                pos += 1
            elif pos >= len_str or timestr[pos:pos+1] not in '0123456789':
                break

    # Handle fractional seconds
    if pos < len_str and timestr[pos:pos+1] in '.,':
        pos += 1
        microsecond_chars = b''
        while pos < len_str and timestr[pos:pos+1].isdigit():
            microsecond_chars += timestr[pos:pos+1]
            pos += 1

        if len(microsecond_chars) > 0:
            # Pad or truncate to 6 digits
            microsecond_str = (microsecond_chars + b'000000').decode('ascii')[:6]
            comps[3] = int(microsecond_str)
        else:
            comps[3] = 0
    else:
        comps[3] = 0

    # Handle timezone
    if pos < len_str:
        tz_str = timestr[pos:]
        comps.append(self._parse_tzstr(tz_str, zero_as_utc=True))
    else:
        comps.append(None)

    # Check for T24:00:00 - special case per ISO 8601
    hour, minute, second, microsecond, tzinfo = comps
    if hour == 24:
        if minute != 0 or second != 0 or microsecond != 0:
            raise ValueError('Hour is 24, but minute, second, or microsecond is non-zero')
        # Return 00:00:00 of the next day by returning (0, 0, 0, 0) and signaling day increment
        return (0, 0, 0, 0, tzinfo, True)  # True indicates we need to add a day

    return (hour if hour is not None else 0, 
            minute if minute is not None else 0, 
            second if second is not None else 0, 
            microsecond if microsecond is not None else 0, 
            tzinfo, 
            False)

